+  if (Number.isFinite(spell.maxTargets) && Number(spell.maxTargets) > 1) {
+    lines.push(`Hits up to ${Number(spell.maxTargets) | 0} targets`);
+  }
+
+  const effects = Array.isArray(spell.effects) ? spell.effects : [];
+  for (const effect of effects) {
