/**
 * @param {World} world
 * @param {number} actor
 * @param {{ id:string }} intendedSpell
 * @param {string[]} learnedSpellIds
 * @returns {{ kind: "normal"|"miscast"|"fizzle", spell: any }}
 */
function resolveConfusedCast(world, actor, intendedSpell, learnedSpellIds) {
  const confusePower = statusStrength(world, actor, "confused");
  if (confusePower <= 0) return { kind: "normal", spell: intendedSpell };
  // Spells marked clearMindedCasting resolve normally even when confused
  // (e.g. blink handles confusion inside its own targeting, flash_heal is
  // a desperate reflex, phase_strike muscle memory).
  if (intendedSpell?.clearMindedCasting) {
    return { kind: "normal", spell: intendedSpell };
  }

  const alternatives = [];
  for (let i = 0; i < learnedSpellIds.length; i++) {
    const id = normalizeSpellId(learnedSpellIds[i]);
    if (!id || id === intendedSpell.id) continue;
    const def = getSpell(id);
    if (def) alternatives.push(def);
  }
  if (alternatives.length === 0) return { kind: "fizzle", spell: intendedSpell };

  const salt = hashString32(intendedSpell.id) ^ 0xC05FACE;
  const r = mulberry32(combatSeed(world.seed, world.step, actor, alternatives.length, salt));
  const idx = (r() * alternatives.length) | 0;
  return { kind: "miscast", spell: alternatives[idx] };
}

/**
 * Resolve CastSpellIntent:
 * - Validate that actor knows the spell
 * - Check resource (mana/stamina/life) and deduct cost
 * - Confused casters miscast to another learned spell, or fizzle if none exists
 * - Emit 'castSpell' semantic event for bridge/display to react to
 * - Clear intent
 * Emits on failure:
 * - 'spell:unknown' | 'spell:not-known' | 'spell:oom' | 'spell:fizzle'
 * @param {World} world
 */
export function castSpellSystem(world) {
  for (const [actor, intent] of world.query(CastSpellIntent)) {
    /** @type {{ learnedSpellIds?: string[] }|null} */
    const brain0 = /** @type any */ (world.get(actor, Brain));
    let spellId = normalizeSpellId(intent?.spellId);
    const learned0 = normalizedLearnedSpellIds(brain0);
    // If no spell specified, default to first learned
    if (!spellId) {
      const first = learned0[0] || null;
      if (first) spellId = first;
    }
    const spell = getSpell(spellId);
    if (!spell) {
      world.emit('spell:unknown', { actor, spellId });
      world.remove(actor, CastSpellIntent);
      continue;
    }

    const interruption = getChannelInterruptionReason(world, actor);
    if (interruption) {
      world.emit("spell:fizzle", {
        actor,
        spellId: spell.id,
        reason: interruption,
      });
      world.remove(actor, CastSpellIntent);
      continue;
    }

    const targetId = Number(intent?.targetId || 0) | 0;
    dealDamage(world, buildSpellDamageSpec(world, actor, targetId, {
      spell,
      baseAmount: amount,
      type: 'holy',
      cause: 'spell:heal',
      at: targetPos,
      salt: 0x4EA1,
    }));
    world.emit('spell:heal:undead', { actor, targetId, at: targetPos, amount });
    return;
  }

  // Check if target needs healing
  const vit = /** @type any */ (world.get(targetId, Vitality));
  const hpCap = effectiveMaxHp(world, targetId, vit);
  if (!vit || (vit.hp | 0) >= hpCap) {
    world.emit('spell:heal', { actor, targetId, at: targetPos, amount: 0, reason: 'full_health' });
    return;
  }

  const actualHeal = applyHealing(world, {
    target: targetId,
    amount,
    source: actor,
    cause: 'spell:heal',
  }).amount;
  world.emit('spell:heal', { actor, targetId, at: targetPos, amount: actualHeal });
};

function resolveHealingTarget(world, actor, spell, intent) {
  const apos = /** @type any */ (world.get(actor, Position));
  if (!apos) return null;
  const targetId = Number(intent?.targetId || 0) | 0;
  const target = targetId > 0 ? targetId : actor;
  const tpos = /** @type any */ (world.get(target, Position));
  const vit = /** @type any */ (world.get(target, Vitality));
  const actorFaction = String(world.get(actor, Faction)?.key || '');
  const targetFaction = String(world.get(target, Faction)?.key || '');
  const range = Math.max(1, Number(spell?.range || 6) | 0);
  if (!tpos || !vit || (vit.hp | 0) <= 0) return null;
  if (target !== actor && (!actorFaction || actorFaction !== targetFaction)) return null;
  if (chebyshev(apos, tpos) > range) return null;
  return { target, pos: { x: tpos.x | 0, y: tpos.y | 0 }, vit };
}

function applyRenewalEffect(world, actor, target, spell, amount, turns) {
  const ae = ensureActiveEffects(world, target);
  if (!ae) return;
  upsertTimedEffect(ae.effects, {
    key: 'renewal',
    turnsLeft: turns,
    potency: amount,
    stacks: 1,
    startedAtTurn: world.step,
    sourceId: actor,
    spellId: spell?.id || 'renewal',
  });
}

REGISTRY['renewal'] = function renewalScript(world, actor, spell, intent) {
  const resolved = resolveHealingTarget(world, actor, spell, intent);
  if (!resolved) {
    world.emit('spell:renewal', { actor, targetId: Number(intent?.targetId || actor) | 0, amount: 0, reason: 'invalid_target' });
    return;
  }
  const brain = /** @type any */ (world.get(actor, Brain));
  const intBonus = brain?.intelligence ? Math.max(0, Math.floor((brain.intelligence - 10) / 2)) : 0;
  const perTick = 2 + Math.floor(intBonus / 2);
  applyRenewalEffect(world, actor, resolved.target, spell, perTick, 5);
  world.emit('spell:renewal', {
    actor,
    targetId: resolved.target,
    at: resolved.pos,
    amount: 0,
    overTime: perTick,
    turns: 5,
  });
};

REGISTRY['sacred_restoration'] = function sacredRestorationScript(world, actor, spell, intent) {
  const resolved = resolveHealingTarget(world, actor, spell, intent);
  if (!resolved) {
    world.emit('spell:sacred_restoration', { actor, targetId: Number(intent?.targetId || actor) | 0, amount: 0, reason: 'invalid_target' });
    return;
  }
  const brain = /** @type any */ (world.get(actor, Brain));
  const intBonus = brain?.intelligence ? Math.max(0, Math.floor((brain.intelligence - 10) / 2)) : 0;
  const amount = 42 + intBonus * 3;
  const healed = applyHealing(world, {
    target: resolved.target,
    amount,
    source: actor,
    cause: 'spell:sacred_restoration',
  }).amount;
  world.emit('spell:sacred_restoration', { actor, targetId: resolved.target, at: resolved.pos, amount: healed });
};

REGISTRY['lifebloom'] = function lifebloomScript(world, actor, spell, _intent) {
  const apos = /** @type any */ (world.get(actor, Position));
  if (!apos) return;
  const actorFaction = String(world.get(actor, Faction)?.key || '');
  const radius = Math.max(1, Number(spell?.radius || 3) | 0);
  const amount = 5 + Math.max(0, Math.floor((Number(world.get(actor, Brain)?.intelligence || 10) - 10) / 3));
  const affected = [];
  for (const [id, pos, fac, vit] of world.query(Position, Faction, Vitality)) {
    if (!pos || !fac || !vit || (vit.hp | 0) <= 0) continue;
    if (String(fac.key || '') !== actorFaction) continue;
    if (chebyshev(apos, pos) > radius) continue;
    const healed = applyHealing(world, { target: id, amount, source: actor, cause: 'spell:lifebloom' }).amount;
    if (healed > 0) affected.push({ id, amount: healed });
  }
  world.emit('spell:lifebloom', {
    actor,
    at: { x: apos.x | 0, y: apos.y | 0 },
    radius,
    amount,
    affected,
    tick: !!_intent?._channelTick,
  });
};

// Flash Heal — high-cost, self-only instant heal.
REGISTRY['flash_heal'] = function flashHealScript(world, actor, spell, intent) {
  const apos = /** @type any */ (world.get(actor, Position));
  if (!apos) return;

  const vit = /** @type any */ (world.get(actor, Vitality));
